  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    'As verificações de origem usam HTTP GET. As execuções automáticas inalteradas ignoram o agente. Um ponteiro JSON opcional monitora apenas esse valor e ignora a ordem das chaves do objeto. Testes manuais sempre são executados. Horários silenciosos adiam relatórios de bot bem-sucedidos. Falhas e aprovações permanecem visíveis. Os limites de uso podem ser ultrapassados ​​quando os relatórios chegam atrasados.',
