  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Este tópico permanece somente leitura. Tente novamente a mudança ou cancele-a. Cancel desbloqueia o thread somente depois que {value0} confirma que removeu sua cópia. Se {value1} já recebeu o encadeamento, cancelar finaliza a movimentação.',
