  'Project copy progress': 'Progresso da cópia do projeto',
  'This thread continues on {value0}. Open it there and send your next message. The copy here stays read-only for recovery.':
    'Este tópico continua em {value0}. Abra aí e envie sua próxima mensagem. A cópia aqui permanece somente leitura para recuperação.',
