  'Cancel move': 'Cancelar mudança',
  'Cancel copy': 'Cancelar cópia',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Mova toda a conversa, lista de verificação, anexos e arquivos salvos. As sessões e credenciais do provedor ficam aqui. O thread de destino usa o equipamento padrão desse computador, sem mais acesso do que este thread tem. Nada funciona até você enviar a próxima mensagem para lá. Você pode alterar seu modelo depois de aberto. Este tópico permanece aqui, somente leitura, para recuperação.',
