  'Setup runs in each new worktree using this runtime’s shell, before the agent starts. Five-minute limit. Failures stop startup; retrying the task retries setup. Use an idempotent command.':
    'A instalação é executada em cada nova árvore de trabalho usando o shell desse tempo de execução, antes do agente ser iniciado. Limite de cinco minutos. Falhas interrompem a inicialização; tentar novamente a configuração de novas tentativas de tarefa. Use um comando idempotente.',
