  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Configure o CuaDriver neste host de tempo de execução. CuaDriver possui permissões de sistema operacional; Dovo conecta agentes por meio do MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Host nomes ou caminhos de executáveis, sem aspas de shell. As substituições do agente têm precedência. Novos terminais usam essas configurações de shell.',
  'Loading {value0} settings…': 'Carregando configurações {value0}…',
  'computer-use': 'uso do computador',
  command: 'comando',
  'Shell arguments (one per line)': 'Argumentos de shell (um por linha)',
  'Automatic shell: {value0}. Default: -l (login shell).':
    'Concha automática: {value0}. Padrão: -l (shell de login).',
  'Enable agent computer use on this computer':
    'Habilitar o uso do computador agente neste computador',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Concede aos agentes graváveis acesso à área de trabalho deste computador. Os agentes somente leitura são excluídos. O usuário e os agentes compartilham o estado da área de trabalho e do aplicativo.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Deixe o Cua Driver vazio para detectá-lo no PATH deste computador ou em sua pasta de instalação padrão. As alterações se aplicam a turnos de novos agentes.',
  '1. Install on this computer': '1. Instale neste computador',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Execute o instalador oficial no host de tempo de execução e atualize o status. Baixe e instale o CuaDriver; nenhuma conta Cua é necessária.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Os sistemas Linux mínimos precisam de libxi6 e at-spi2-core. O GNOME precisa do ajudante WinRects incluído no Cua; consulte o guia de instalação.',
  'Install and set up Cua Driver': 'Instalar e configurar o driver Cua',
  'Detect / check Cua Driver': 'Detectar / verificar o driver Cua',
  '2. Permissions & desktop access': '2. Permissões e acesso à área de trabalho',
  '3. Agent MCP, skills & hooks': '3. Agente MCP, habilidades e ganchos',
  '4. Computer History (optional preview)': '4. Histórico do computador (visualização opcional)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Conceda acessibilidade do macOS e gravação de tela ao CuaDriver e aceite seu relançamento. Teste aplicativos de listas de acesso de desktop sem alterá-los. Os controles daemon afetam as sessões ativas de uso do computador.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Salve a opção de uso do computador para dovo_cua MCP automático em novos turnos graváveis. Nenhum registro manual do MCP é necessário. Instale o pacote de habilidades oficial opcional; links de instalação detectaram agentes neste computador.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Histórico opt-in, criptografado e somente metadados. Enable pode reiniciar o daemon. Desabilitar mantém os dados registrados; pausa interrompe temporariamente a gravação. Compilações não suportadas relatam um erro. Os dados permanecem no host de tempo de execução; Veja o histórico recente recupera até 20 eventos aqui.',
  'Delete recorded Computer History?': 'Excluir o histórico do computador gravado?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Exclua todo o histórico gravado e sua chave de criptografia neste computador. Isto não pode ser desfeito.',
