  'Switches and choices save automatically. Text fields show a Save button.':
    'As opções e opções são salvas automaticamente. Os campos de texto mostram um botão Salvar.',
  'Computer defaults apply when scoped Task lifecycle settings inherit. Scoped restart and archiving rules take precedence.':
    'Os padrões do computador se aplicam quando as configurações do ciclo de vida da tarefa com escopo são herdadas. As regras de reinicialização e arquivamento com escopo definido têm precedência.',
  'Open scoped task lifecycle': 'Ciclo de vida de tarefas com escopo aberto',
  'Saved on this computer and shared with its paired devices. Switches and choices save automatically.':
    'Salvo neste computador e compartilhado com os dispositivos emparelhados. As opções e opções são salvas automaticamente.',
  'This computer is offline. Reconnect to load and change its preferences.':
    'Este computador está off-line. Reconecte para carregar e alterar suas preferências.',
  'Loading computer preferences…': 'Carregando preferências do computador…',
  'Retry computer preferences': 'Tente novamente as preferências do computador',
