  'Save branch prefix': 'Salvar prefixo de filial',
  'Remove worktrees of archived tasks': 'Remover árvores de trabalho de tarefas arquivadas',
  'Worktrees with uncommitted changes are kept. The branch stays, so restoring a task checks it out again. Ignored local files are deleted with the checkout.':
    'As árvores de trabalho com alterações não confirmadas são mantidas. A ramificação permanece, portanto, restaurar uma tarefa verifica-a novamente. Arquivos locais ignorados são excluídos na finalização da compra.',
  'Remove worktrees when deleting their last thread':
    'Remova as árvores de trabalho ao excluir o último tópico',
  'Only clean Dovo-created checkouts with no remaining threads are removed. Branches and uncommitted changes are kept. Ignored local files are deleted with the checkout.':
    'Somente checkouts limpos criados pelo Dovo sem threads restantes são removidos. Ramificações e alterações não confirmadas são mantidas. Arquivos locais ignorados são excluídos na finalização da compra.',
  'Capture repeated freezes': 'Capture congelamentos repetidos',
  'After two busy stalls, sample CPU work for two seconds. Keep three local summaries without source paths or user code. At most once per ten minutes. Off by default.':
    'Após duas paralisações ocupadas, teste o funcionamento da CPU por dois segundos. Mantenha três resumos locais sem caminhos de origem ou código de usuário. No máximo uma vez a cada dez minutos. Desativado por padrão.',
  'Keep activity history': 'Mantenha o histórico de atividades',
  Forever: 'Para sempre',
  'For 1 year': 'Por 1 ano',
  'For 90 days': 'Por 90 dias',
  'For 30 days': 'Por 30 dias',
  'Older requests and tool details are deleted from this computer. Task conversations are kept. CLI diagnostics and raw provider events expire after {value0} days, including when activity history is kept forever. Successful Git and GitHub reads are not recorded.':
    'Solicitações mais antigas e detalhes de ferramentas são excluídos deste computador. As conversas de tarefas são mantidas. Os diagnósticos CLI e os eventos brutos do provedor expiram após {value0} dias, inclusive quando o histórico de atividades é mantido para sempre. As leituras bem-sucedidas do Git e do GitHub não são registradas.',
  'Maximum concurrent child agents': 'Máximo de agentes filhos simultâneos',
  'Per parent thread on this computer. Extra launches are refused until a child finishes; existing children keep running when the limit is lowered. Default: 4.':
    'Por thread pai neste computador. Lançamentos extras são recusados ​​até que a criança termine; as crianças existentes continuam correndo quando o limite é reduzido. Padrão: 4.',
  'Save child agent limit': 'Salvar limite de agente filho',
  'Enable internet access for this paired computer without scanning another QR. Stay connected over LAN or VPN until approval finishes.':
    'Habilite o acesso à Internet para este computador emparelhado sem digitalizar outro QR. Permaneça conectado por LAN ou VPN até a aprovação terminar.',
  'Testing and saving internet connection…': 'Testando e salvando conexão com a internet…',
  'Waiting for approval on the computer. In Dovo, open Settings → Devices & runtime → Trusted devices. On a server, run dovo-server pair devices, then dovo-server pair approve <request-id>.':
    'Aguardando aprovação no computador. No Dovo, abra Configurações → Dispositivos e tempo de execução → Dispositivos confiáveis. Em um servidor, execute dovo-server pair devices e, em seguida, dovo-server pair aprovar <request-id>.',
  'Cancel internet request': 'Cancelar solicitação de internet',
