  'Leave Artifacts blank to use the store announced by Connect. Configure the same custom URL on your Connect broker and artifact server; Studio checks they match before sharing.':
    'Deixe Artefatos em branco para usar a loja anunciada pelo Connect. Configure o mesmo URL customizado em seu agente Connect e servidor de artefato; O Studio verifica se elas correspondem antes de compartilhar.',
