  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Este telefone não está mais emparelhado com o computador abaixo. Ele foi removido desse computador ou o tempo de execução foi redefinido. Emparelhe-o novamente em Dispositivos em Configurações.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Conectado usando atualizações HTTP. A transmissão ao vivo está sendo reconectada ou indisponível. Reconecte para tentar novamente.',
