  'Access to this computer was renewed. Some saved actions may already have run and retrying could repeat them. Check the computer before continuing. Messages keep their original delivery identity.':
    'O acesso a este computador foi renovado. Algumas ações salvas podem já ter sido executadas e tentar novamente pode repeti-las. Verifique o computador antes de continuar. As mensagens mantêm sua identidade de entrega original.',
  'Discard saved actions': 'Descartar ações salvas',
  'Discard saved actions?': 'Descartar ações salvas?',
  'Actions already applied on the computer will remain applied. Unsent actions will be removed from this phone.':
    'As ações já aplicadas no computador permanecerão aplicadas. As ações não enviadas serão removidas deste telefone.',
