  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Parear novamente',
  'Connection stages': 'Estágios de conexão',
  'Start your computer': 'Inicie o seu computador',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Abra o Dovo no seu computador e mantenha-o ativo. Em Configurações → Dispositivos e tempo de execução, faça login e ative o Dovo Connect. Faça login na mesma conta em seu telefone e escolha Conectar. Nenhum código de emparelhamento, VPN ou IP local é necessário para acesso à Internet.',
  'Direct internet connection': 'Conexão direta com a Internet',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN conecta seu telefone diretamente ao computador. Seu conteúdo é criptografado de ponta a ponta. A ativação do Dovo Connect permite um fallback de retransmissão criptografada se uma rede bloquear conexões diretas. A retransmissão encaminha o tráfego criptografado; ele não pode ler seu conteúdo.',
  'LAN / VPN connections': 'Conexões LAN/VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Emparelhe LAN/VPN separadamente para preferir essa conexão quando disponível. Copie o endereço Wi-Fi, Tailscale, NetBird ou HTTPS completo mostrado em seu computador, incluindo sua porta. localhost e 0.0.0.0 não são endereços aos quais seu telefone pode se conectar.',
  'Check your network': 'Verifique sua rede',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Use o mesmo Wi-Fi ou conecte os dois dispositivos à sua VPN. Para conexões Wi-Fi, permita o acesso do Dovo à sua rede local nas configurações do iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Os códigos de emparelhamento expiram após dois minutos. Os códigos CLI são aprovados automaticamente; um código da área de trabalho pode precisar de aprovação lá.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Seu emparelhamento foi salvo. Tente Reconectar antes de gerar outro código. Se o endereço mudou, escolha Atualizar endereço de conexão nas configurações deste computador.',
