  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Executa o agente de cada nova conversa, os seus comandos e os seus terminais num contêiner local do Docker ou Podman. Só a cópia de trabalho e o login do agente escolhido são montados. As conversas em curso mantêm a sua configuração.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Sem acesso à rede, o agente não consegue alcançar a API do seu modelo, a menos que essa API seja executada dentro do sandbox. Instalações de pacotes e pedidos web também falham.',
